import{_ as a,a as t,o as r,a2 as s}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Generative AI (Magic AI)","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/introduction.md","filePath":"generative-ai/introduction.md","lastUpdated":1789411722000}'),n={name:"generative-ai/introduction.md"};function o(i,e,c,l,d,h){return r(),t("div",null,e[0]||(e[0]=[s('<h1 id="generative-ai-magic-ai" tabindex="-1">Generative AI (Magic AI) <a class="header-anchor" href="#generative-ai-magic-ai" aria-label="Permalink to &quot;Generative AI (Magic AI)&quot;">​</a></h1><div class="feature-hero feature--ai"><span class="feature-hero__eyebrow">Built into Bagisto</span><p class="feature-hero__lead">Write product content, create product images, translate reviews and personalize order confirmations with the AI provider you choose. Branded <strong>Magic AI</strong> in the admin panel, it is part of Bagisto itself, with nothing extra to install.</p><div class="feature-hero__actions"><a class="feature-hero__btn feature-hero__btn--primary" href="/configure/magic-ai.html">Set up Generative AI</a><a class="feature-hero__btn feature-hero__btn--ghost" href="#what-you-can-do">Explore the features</a></div><ul class="feature-hero__chips" aria-label="Supported AI providers"><li>OpenAI</li><li>Anthropic</li><li>Gemini</li><li>Groq</li><li>xAI</li><li>DeepSeek</li><li>Mistral</li><li>Ollama</li></ul></div><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><div class="feature-cards feature--ai"><a class="feature-card" href="/generative-ai/generate-content.html"><span class="feature-card__icon feature-card__icon--text" aria-hidden="true"></span><span class="feature-card__title">Generate text content</span><span class="feature-card__desc">Draft product and category descriptions, CMS pages and email templates from a prompt, right in the editor.</span><span class="feature-card__tag">Admin panel</span></a><a class="feature-card" href="/generative-ai/generate-images.html"><span class="feature-card__icon feature-card__icon--image" aria-hidden="true"></span><span class="feature-card__title">Generate product images</span><span class="feature-card__desc">Create images from a written description, in the size and quality you choose, and keep the ones you like.</span><span class="feature-card__tag">Admin panel</span></a><a class="feature-card" href="/generative-ai/image-search.html"><span class="feature-card__icon feature-card__icon--camera" aria-hidden="true"></span><span class="feature-card__title">AI image search</span><span class="feature-card__desc">Shoppers search with a photo. The model describes what is in it, and the store finds matching products.</span><span class="feature-card__tag">Storefront</span></a><a class="feature-card" href="/generative-ai/review-translation.html"><span class="feature-card__icon feature-card__icon--translate" aria-hidden="true"></span><span class="feature-card__title">Review translation</span><span class="feature-card__desc">Shoppers read any product review in their own language with one click on <strong>Translate</strong>.</span><span class="feature-card__tag">Storefront</span></a><a class="feature-card" href="/generative-ai/checkout-message.html"><span class="feature-card__icon feature-card__icon--message" aria-hidden="true"></span><span class="feature-card__title">Personalized checkout message</span><span class="feature-card__desc">Thank each customer on the order confirmation page with a short message about what they bought.</span><span class="feature-card__tag">Storefront</span></a><a class="feature-card" href="/configure/magic-ai.html"><span class="feature-card__icon feature-card__icon--settings" aria-hidden="true"></span><span class="feature-card__title">Configuration</span><span class="feature-card__desc">Switch Generative AI on, connect your providers and choose the model each feature uses.</span><span class="feature-card__tag">Configure &gt;&gt; Magic AI</span></a></div><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol class="feature-steps feature--ai"><li><span class="feature-steps__title">Connect a provider</span>Add an API key for OpenAI, Anthropic, Gemini, Groq, xAI, DeepSeek or Mistral, or the address of your own Ollama server.</li><li><span class="feature-steps__title">Switch on the features</span>Choose the features you want, the providers admins can pick from, and the model each storefront feature runs on.</li><li><span class="feature-steps__title">Review, then apply</span>Admin features show their result in a dialog first. Nothing is added to your store until you click <strong>Apply</strong>.</li></ol><ul><li><strong>Your provider, your model.</strong> In the admin panel you pick a model each time you generate. Each storefront feature uses the model you set for it on each channel. Ollama runs open models on your own server, so requests to it stay on your own infrastructure.</li><li><strong>Admin features suggest, you decide.</strong> Generated text and images go into the product, page or template only when you click <strong>Apply</strong>.</li><li><strong>Storefront features respond to the shopper.</strong> A photo is analyzed when the shopper searches with it, a review is translated when they click <strong>Translate</strong>, and the checkout message is written when the order confirmation page opens.</li></ul><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>All settings live under <strong>Configure &gt;&gt; Magic AI</strong>. Follow <a href="./../configure/magic-ai.html">Generative AI Configuration</a> to switch the features on, connect a provider and choose models, then open the page for the feature you want to use.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><p>Magic AI does not run the store by itself. It does not publish content, change prices, place orders or answer customers. Everything it produces in the admin panel is reviewed and applied by you, and on the storefront it only reacts to what the shopper does. Text and images from an AI model can be wrong or misleading, which is why the admin dialogs ask you to review the result before applying it.</p>',11)]))}const f=a(n,[["render",o]]);export{p as __pageData,f as default};
